local x=np.transpose(np.astype(np.arange(0,"int64"):reshape({2,0}),"float64"),{2,1})
local before=x:tolist()
local out=np.zeros({0,2},"float64")
local y=r:permuted(x,1,out)
deep(y.dtype,"float64","9876/(2, 0)/float64/transpose/0/out_new dtype")
deep(y:tolist(),{},"9876/(2, 0)/float64/transpose/0/out_new values")
deep(x:tolist(),{},"9876/(2, 0)/float64/transpose/0/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"b42062a2610530af","9876/(2, 0)/float64/transpose/0/out_new pcg")
cases=cases+1; end
