deep(x:tolist(),{{},{},{}},"9876/(2, 0, 3)/int64/transpose/0/copy source")
deep(r:raw_hex(),"b42062a2610530af","9876/(2, 0, 3)/int64/transpose/0/copy pcg")
cases=cases+1; end
