local x=np.transpose(np.astype(np.arange(0,"int64"):reshape({2,0,3}),"float32"),{3,2,1})
local before=x:tolist()
local y=r:permuted(x,1)
deep(y.dtype,"float32","9876/(2, 0, 3)/float32/transpose/0/copy dtype")
deep(y:tolist(),{{},{},{}},"9876/(2, 0, 3)/float32/transpose/0/copy values")
deep(x:tolist(),{{},{},{}},"9876/(2, 0, 3)/float32/transpose/0/copy source")
deep(r:raw_hex(),"b42062a2610530af","9876/(2, 0, 3)/float32/transpose/0/copy pcg")
cases=cases+1; end
