local x=np.transpose(np.astype(np.arange(0,"int64"):reshape({2,0,3}),"uint8"),{3,2,1})
local before=x:tolist()
local out=np.zeros({3,0,2},"uint8")
local y=r:permuted(x,-1,out)
deep(y.dtype,"uint8","9876/(2, 0, 3)/uint8/transpose/-1/out_new dtype")
deep(y:tolist(),{{},{},{}},"9876/(2, 0, 3)/uint8/transpose/-1/out_new values")
deep(x:tolist(),{{},{},{}},"9876/(2, 0, 3)/uint8/transpose/-1/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"b42062a2610530af","9876/(2, 0, 3)/uint8/transpose/-1/out_new pcg")
cases=cases+1; end
