local x=np.transpose(np.astype(np.arange(24,"int64"):reshape({2,3,4}),"int32"),{3,2,1})
local before=x:tolist()
local out=np.zeros({4,3,2},"int32")
local y=r:permuted(x,3,out)
deep(y.dtype,"int32","9876/(2, 3, 4)/int32/transpose/2/out_new dtype")
deep(y:tolist(),{{{0,12},{16,4},{8,20}},{{1,13},{5,17},{9,21}},{{2,14},{18,6},{22,10}},{{3,15},{19,7},{23,11}}},"9876/(2, 3, 4)/int32/transpose/2/out_new values")
